sys_script_include.script:
var ExtractionApplier = Class.create();
ExtractionApplier.prototype = {
    initialize: function() {
        this.ENTITY = 'x_gegis_ins_policy_extraction_entity';
        this.FIELD = 'x_gegis_ins_policy_extraction_field';
        this.APPLIABLE = 'accepted,auto_accepted,corrected';
    },

    /**
     * Apply one reviewed extraction to the system of record.
     * Accepted entities become (or update) target records; accepted and
     * corrected fields write their final value onto the target column.
     * Runs as the session user so sys_audit attributes changes correctly.
     *
     * @param extractionGr GlideRecord x_gegis_ins_policy_extraction
     * @return Number of field values applied
     */
    apply: function(extractionGr) {
        var extractionId = extractionGr.getUniqueValue();
        var submissionId = String(extractionGr.submission);
        var entityTarget = this._materializeEntities(extractionId, submissionId);

        var applied = 0;
        var f = new GlideRecord(this.FIELD);
        f.addQuery('extraction', extractionId);
        f.addQuery('review_status', 'IN', this.APPLIABLE);
        f.query();
        while (f.next()) {
            var targetId = f.entity ? entityTarget[String(f.entity)] : '';
            if (!targetId && String(f.target_table) === 'x_gegis_ins_policy_submission')
                targetId = submissionId;
            if (!targetId)
                continue;
            if (this._writeValue(f, targetId)) {
                f.target_sys_id = targetId;
                f.applied_by = gs.getUserID();
                f.applied_on = new GlideDateTime();
                f.review_status = 'applied';
                f.update();
                applied++;
            }
        }

        extractionGr.disposition = 'applied';
        extractionGr.extraction_status = 'reviewed';
        extractionGr.update();
        this._touchSubmission(submissionId, extractionId);
        return applied;
    },

    /** The agreed truth for a field: override wins, then mapped, then raw. */
    getFinalValue: function(fieldGr) {
        var override = String(fieldGr.override_value);
        if (override)
            return override;
        var mapped = String(fieldGr.mapped_value);
        return mapped ? mapped : String(fieldGr.extracted_value);
    },

    /** Create target records for accepted entities; reuse matched ones. */
    _materializeEntities: function(extractionId, submissionId) {
        var map = {};
        var e = new GlideRecord(this.ENTITY);
        e.addQuery('extraction', extractionId);
        e.addQuery('disposition', 'IN', 'accepted,merged');
        e.query();
        while (e.next()) {
            var targetId = String(e.matched_record);
            var table = String(e.matched_table);
            if (!targetId) {
                table = 'x_gegis_ins_policy_' + String(e.entity_type);
                var t = new GlideRecord(table);
                if (!t.isValid())
                    continue;
                t.initialize();
                if (t.isValidField('submission'))
                    t.submission = submissionId;
                targetId = t.insert();
                e.matched_table = table;
                e.matched_record = targetId;
                e.match_status = 'matched';
                e.update();
            }
            map[e.getUniqueValue()] = targetId;
        }
        return map;
    },

    _writeValue: function(fieldGr, targetId) {
        var gr = new GlideRecord(String(fieldGr.target_table));
        if (!gr.isValid() || !gr.get(targetId))
            return false;
        var column = String(fieldGr.target_column);
        if (!gr.isValidField(column))
            return false;
        gr.setValue(column, this.getFinalValue(fieldGr));
        gr.update();
        return true;
    },

    _touchSubmission: function(submissionId, extractionId) {
        if (!submissionId)
            return;
        var sub = new GlideRecord('x_gegis_ins_policy_submission');
        if (sub.get(submissionId)) {
            sub.current_extraction = extractionId;
            sub.extraction_status = 'applied';
            sub.update();
        }
    },

    type: 'ExtractionApplier'
};
